let actx;
function ac(){ try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); if (actx.state === "suspended") actx.resume(); } catch (e) {} return actx; }
function chime(base, gain, when){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + .02 + (when || 0), out = c.createGain(); out.gain.value = gain || .08; out.connect(c.destination);
    [[1, 1, 1.6], [2, .35, 1.1], [3, .12, .7]].forEach(([r, g, d]) => {
      const o = c.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = c.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .01); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
function noise(dur, freq, q, gain, type){
  const c = ac(); if (!c) return;
  try {
    const n = Math.floor(c.sampleRate * dur), b = c.createBuffer(1, n, c.sampleRate), ch = b.getChannelData(0);
    for (let i = 0; i < n; i++) ch[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / n, type === "pop" ? 6 : 1.6);
    const s = c.createBufferSource(); s.buffer = b;
    const f = c.createBiquadFilter(); f.type = type === "pop" ? "bandpass" : "lowpass"; f.frequency.value = freq; f.Q.value = q;
    if (type !== "pop") f.frequency.exponentialRampToValueAtTime(240, c.currentTime + dur);
    const g = c.createGain(); g.gain.value = gain; s.connect(f); f.connect(g); g.connect(c.destination); s.start();
  } catch (e) {}
}
