function confetti(x, y, n, power){
  if (calm) return;
  for (let i = 0; i < n; i++) { const a = -Math.PI / 2 + (Math.random() - .5) * 2.2, s = power * (.45 + Math.random() * .7); parts.push(piece(x, y, Math.cos(a) * s, Math.sin(a) * s)); }
