function startC(){ if (parts.length > 500) parts.splice(0, parts.length - 500); if (!cRun) { cRun = true; cLast = performance.now(); requestAnimationFrame(stepC); } }
function stepC(t){
  const dt = Math.min(.033, (t - cLast) / 1000); cLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  parts = parts.filter(p => p.y < innerHeight + 40);
  for (const p of parts) {
    p.vy = Math.min(p.vy + 900 * dt, 230); p.vx *= .985;
    p.x += (p.vx + Math.sin(t / 300 + p.ph) * 30) * dt; p.y += p.vy * dt; p.r += p.vr * dt;
    cx.save(); cx.translate(p.x, p.y); cx.rotate(p.r); cx.scale(1, Math.cos(p.r * 1.7)); cx.fillStyle = p.c;
    if (p.round) { cx.beginPath(); cx.arc(0, 0, p.w / 2, 0, 6.3); cx.fill(); } else cx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
    cx.restore();
  }
  if (parts.length) requestAnimationFrame(stepC); else { cRun = false; cx.clearRect(0, 0, innerWidth, innerHeight); }
}

