  const lines = ["RSVP · Diya's 1st Birthday 🎈", "", "Name: " + name, "Coming: " + (yes ? "Yes, we'll be there!" : "Sorry, can't make it")];
  if (yes) { lines.push("Adults: " + cnt.a); lines.push("Kids: " + cnt.k); }
  const w = $("r-msg").value.trim(); if (w) lines.push("Note: " + w);
  const url = "https://wa.me/" + WA + "?text=" + encodeURIComponent(lines.join("\n"));
  const win = FMI.open(url, "_blank"); if (!win) FMI.open(url);
});

/* the candle */
const cake = $("cake");
let blown = false;
function blow(){
  blown = !blown;
  cake.classList.toggle("out", blown);
  if (blown) {
    noise(.55, 1400, .6, .35); setTimeout(fanfare, 250);
    $("cake-h").textContent = "Happy 1st Birthday, Diya!";
    $("cake-sub").textContent = "Your wish is on its way. See you at the party!";
    $("blow").textContent = "Light it again"; cake.setAttribute("aria-label", "Light the candle again");
    setTimeout(() => rain(240), 300);
  } else {
    chime(659.25, .07);
    $("cake-h").textContent = "Make a wish, Diya!";
    $("cake-sub").textContent = "Tap the candle to blow it out.";
    $("blow").textContent = "Blow out the candle"; cake.setAttribute("aria-label", "Blow out the candle");
  }
}
cake.addEventListener("click", blow);
$("blow").addEventListener("click", blow);

/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
$("share").addEventListener("click", async () => {
  const url = location.origin + FMI.instanceKey;
  try {
    if (navigator.share) { await FMI.share({ title: "Diya turns one! · Birthday Invitation", text: "You're invited to Diya's 1st birthday party on 13 March 2027", url }); return; }
    await FMI.copyLink(url); toast("Invitation link copied");
  } catch (e) { if (e && e.name !== "AbortError") toast(url); }
});

FMI.ready();
})();
